    pm.response.to.have.status(200);
});

pm.test("Response is an array", function () {
    const data = pm.response.json();
    pm.expect(data).to.be.an("array");
});

const jsonData = pm.response.json();

pm.environment.set(
    "accountId",
    jsonData.accountId
);

console.log(
    "Saved accountId:",
    jsonData.accountId
);

pm.test("Account created", function () {
    pm.response.to.have.status(201);
});

pm.test("Account ID returned", function () {
    const data = pm.response.json();
    pm.expect(data.accountId).to.exist;
});

const jsonData = pm.response.json();

pm.environment.set(
    "recipientId",
    jsonData.accountId
);

console.log(
    "Saved recipientId:",
    jsonData.accountId
);

pm.test("Recipient account created", function () {
    pm.response.to.have.status(201);
});

pm.test("Recipient ID returned", function () {
    const data = pm.response.json();
    pm.expect(data.accountId).to.exist;
});

pm.test("Account retrieved", function () {
    pm.response.to.have.status(200);
});

pm.test("Correct account loaded", function () {
    const data = pm.response.json();

    pm.expect(String(data.accountId))
    .to.eql(pm.environment.get("accountId"));
});

pm.test("Balance retrieved", function () {
